import { createRoot } from 'react-dom/client';
import { Toaster } from 'sonner';
import App from './App';
import './styles.css';

const root = createRoot(document.getElementById('root')!);
root.render(<><App /><Toaster richColors position="top-right" /></>);

:root { color-scheme: light; }
html, body, #root { height: 100%; }
body { margin: 0; background: #ffffff; color: #0a0a0a;
       font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
       -webkit-font-smoothing: antialiased; }

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import { useEffect, useRef, useState, useCallback } from 'react';
import { Play, Pause, RotateCcw } from 'lucide-react';

const COLS = 24;
const ROWS = 24;
const CELL = 18;
const TICK_MS = 110;

type Pt = { x: number; y: number };
type Dir = 'up' | 'down' | 'left' | 'right';

const VECT: Record<Dir, Pt> = {
  up:    { x:  0, y: -1 },
  down:  { x:  0, y:  1 },
  left:  { x: -1, y:  0 },
  right: { x:  1, y:  0 },
};

const OPP: Record<Dir, Dir> = { up: 'down', down: 'up', left: 'right', right: 'left' };

function randCell(occupied: Pt[]): Pt {
  for (let i = 0; i < 256; i++) {
    const p = { x: Math.floor(Math.random() * COLS), y: Math.floor(Math.random() * ROWS) };
    if (!occupied.some((q) => q.x === p.x && q.y === p.y)) return p;
  }
  return { x: 0, y: 0 };
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [snake, setSnake] = useState<Pt[]>(() => [{ x: 12, y: 12 }, { x: 11, y: 12 }, { x: 10, y: 12 }]);
  const [food, setFood] = useState<Pt>(() => ({ x: 17, y: 12 }));
  const [dir, setDir] = useState<Dir>('right');
  const [pendingDir, setPendingDir] = useState<Dir>('right');
  const [score, setScore] = useState(0);
  const [best, setBest] = useState<number>(() => Number(localStorage.getItem('snake.best') || 0));
  const [running, setRunning] = useState(true);
  const [over, setOver] = useState(false);

  const reset = useCallback(() => {
    setSnake([{ x: 12, y: 12 }, { x: 11, y: 12 }, { x: 10, y: 12 }]);
    setFood({ x: 17, y: 12 });
    setDir('right');
    setPendingDir('right');
    setScore(0);
    setRunning(true);
    setOver(false);
  }, []);

  // Tick
  useEffect(() => {
    if (!running || over) return;
    const id = window.setInterval(() => {
      setSnake((prev) => {
        const d = pendingDir;
        setDir(d);
        const head = prev[0];
        const next = { x: head.x + VECT[d].x, y: head.y + VECT[d].y };
        if (next.x < 0 || next.x >= COLS || next.y < 0 || next.y >= ROWS) {
          setOver(true); setRunning(false); return prev;
        }
        if (prev.some((p) => p.x === next.x && p.y === next.y)) {
          setOver(true); setRunning(false); return prev;
        }
        const ate = next.x === food.x && next.y === food.y;
        const grown = ate ? [next, ...prev] : [next, ...prev.slice(0, -1)];
        if (ate) {
          setScore((s) => {
            const ns = s + 1;
            setBest((b) => {
              const nb = Math.max(b, ns);
              localStorage.setItem('snake.best', String(nb));
              return nb;
            });
            return ns;
          });
          setFood(randCell(grown));
        }
        return grown;
      });
    }, TICK_MS);
    return () => window.clearInterval(id);
  }, [running, over, pendingDir, food]);

  // Input
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      const k = e.key.toLowerCase();
      const map: Record<string, Dir> = {
        arrowup: 'up', w: 'up',
        arrowdown: 'down', s: 'down',
        arrowleft: 'left', a: 'left',
        arrowright: 'right', d: 'right',
      };
      const wanted = map[k];
      if (wanted) {
        e.preventDefault();
        if (OPP[wanted] !== dir) setPendingDir(wanted);
        return;
      }
      if (k === ' ') { e.preventDefault(); setRunning((r) => !r); return; }
      if (k === 'r') { e.preventDefault(); reset(); return; }
    }
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [dir, reset]);

  // Render
  useEffect(() => {
    const c = canvasRef.current; if (!c) return;
    const ctx = c.getContext('2d'); if (!ctx) return;
    ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, c.width, c.height);
    // grid hairlines
    ctx.strokeStyle = '#eaeaea'; ctx.lineWidth = 1;
    for (let x = 0; x <= COLS; x++) { ctx.beginPath(); ctx.moveTo(x * CELL + 0.5, 0); ctx.lineTo(x * CELL + 0.5, ROWS * CELL); ctx.stroke(); }
    for (let y = 0; y <= ROWS; y++) { ctx.beginPath(); ctx.moveTo(0, y * CELL + 0.5); ctx.lineTo(COLS * CELL, y * CELL + 0.5); ctx.stroke(); }
    // food
    ctx.fillStyle = '#feeeb2';
    ctx.beginPath();
    ctx.arc(food.x * CELL + CELL / 2, food.y * CELL + CELL / 2, CELL / 2 - 2, 0, Math.PI * 2);
    ctx.fill();
    // snake
    snake.forEach((p, i) => {
      ctx.fillStyle = i === 0 ? '#76b900' : '#6caa00';
      ctx.fillRect(p.x * CELL + 2, p.y * CELL + 2, CELL - 4, CELL - 4);
    });
  }, [snake, food]);

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#ffffff] p-4">
      <div className="rounded-2xl bg-[#f7f7f7] p-4 ring-1 ring-[#eaeaea] shadow-2xl">
        <div className="mb-3 flex items-center justify-between gap-6 text-sm">
          <div className="text-[#0a0a0a] font-semibold">Snake</div>
          <div className="flex gap-4 tabular-nums text-[#525252]">
            <span>Score: <span className="text-[#0a0a0a] font-semibold">{score}</span></span>
            <span>Best: <span className="text-[#0a0a0a] font-semibold">{best}</span></span>
          </div>
        </div>
        <div className="relative" style={{ width: COLS * CELL, height: ROWS * CELL }}>
          <canvas
            ref={canvasRef}
            width={COLS * CELL}
            height={ROWS * CELL}
            className="rounded-lg block"
          />
          {over && (
            <div className="absolute inset-0 flex flex-col items-center justify-center rounded-lg bg-[#ffffff]/85 backdrop-blur-sm">
              <div className="text-2xl font-semibold text-[#0a0a0a] mb-1">Game over</div>
              <div className="text-sm text-[#525252] mb-4">Score {score} · Best {best}</div>
              <button
                onClick={reset}
                className="rounded-full bg-[#76b900] px-5 py-2 text-sm font-medium text-[#0a0a0a] hover:bg-[#6caa00] inline-flex items-center gap-2"
              ><RotateCcw className="h-4 w-4" /> Restart</button>
            </div>
          )}
        </div>
        <div className="mt-3 flex items-center justify-between gap-2 text-xs text-[#525252]">
          <span>Arrow keys / WASD · Space pause · R restart</span>
          <div className="flex gap-2">
            <button
              onClick={() => setRunning((r) => !r)}
              disabled={over}
              className="rounded-md bg-[#efefef] px-2 py-1 text-[#0a0a0a] hover:bg-[#e5e5e5] disabled:opacity-40 inline-flex items-center gap-1"
            >
              {running ? <><Pause className="h-3 w-3" />Pause</> : <><Play className="h-3 w-3" />Play</>}
            </button>
            <button
              onClick={reset}
              className="rounded-md bg-[#efefef] px-2 py-1 text-[#0a0a0a] hover:bg-[#e5e5e5] inline-flex items-center gap-1"
            ><RotateCcw className="h-3 w-3" /> Reset</button>
          </div>
        </div>
      </div>
    </div>
  );
}
